function compile(routes) {
  return routes.map((r) => {
    const names = []
    let src = r.path
      .split('/')
      .filter(Boolean)
      .map((seg) => {
        if (seg.startsWith(':')) {
          const opt = seg.endsWith('?')
          const name = seg.slice(1, opt ? -1 : undefined)
          names.push(name)
          return opt ? '(?:/([^/]+))?' : '/([^/]+)'
        }
        if (seg === '*') return '/?(.*)'
        return '/' + seg.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
      })
      .join('')
    const re = new RegExp('^' + (src || '/?') + '$')
    return { ...r, re, names }
  })
}
function normalize(p) {
  const path = p.split(/[?#]/)[0]
  const merged = path.replace(/\/+/g, '/')
  return merged.length > 1 ? merged.replace(/\/$/, '') : merged || '/'
}
function match(table, rawPath) {
  const path = normalize(rawPath)
  for (const r of table) {
    const m = r.re.exec(path)
    if (!m) continue
    const params = {}
    r.names.forEach((n, i) => { if (m[i + 1] !== undefined) params[n] = decodeURIComponent(m[i + 1]) })
    return { handler: r.handler, params }
  }
  return { notFound: true }
}
